export type FieldType = "int" | "real" | "bool" | "enum" | "optionalInt" | "optionalEnum" | "slot" | "ref" | "optionalRef" | "length";
export type CopyForm = "plain" | "retained" | "none";
export type SameForm = "signedZero" | "signedZeroOptional" | "plain" | "sameReal" | "none";
export type CanonKit = "moves" | "specials" | "placedSpec" | "projectileSpec";
export type CanonWriter = "int" | "real" | "bool" | "boolAsInt" | "flagInt" | "flagBool" | "optionalInt" | "slotRef" | "digest" | "specText";
export type Guard = "specials" | "companion" | "condition" | "poison" | "buff" | "beamPair" | "nonzero" | "nonzeroSigned" | "cooldownSlot" | "defined" | "kobold";
export type ArrayLayout = "fieldMajor" | "animalMajor" | "scalarArray";

export interface CanonColumn {
  readonly name: string;
  readonly writer: CanonWriter;
  readonly when?: readonly Guard[];
  readonly kit?: CanonKit;
  readonly sharedLoop?: true;
}

export interface RespawnColumn {
  readonly blast?: string;
  readonly respawn?: string;
  readonly helper?: string;
}

export type DiffColumn = string | { readonly record: string } | { readonly name: string; readonly absent: number } | "none";

export interface FighterFieldRow {
  readonly path: string;
  readonly type: FieldType;
  readonly init: string;
  readonly copy: CopyForm;
  readonly same: SameForm;
  readonly canon: CanonColumn | "none";
  readonly diff: DiffColumn;
  readonly respawn: RespawnColumn | "keep";
}

export function fighterDiffName(row: FighterFieldRow): string | undefined {
  const diff = row.diff;
  if (diff === "none") return undefined;
  if (typeof diff === "string") return diff;
  return "record" in diff ? diff.record : diff.name;
}

export interface FighterGroup {
  readonly key: string;
  readonly type: string;
  readonly local: string;
  readonly rest?: string;
}

export interface FighterArray {
  readonly path: string;
  readonly capacity: string;
  readonly layout: ArrayLayout;
  readonly mirror?: "inline" | "function";
  readonly iterate?: "target" | "source";
  readonly index?: string;
  readonly bound?: "length" | "capacity";
  readonly fallback?: string;
}

